let currentLang = 'en';

langBtn.addEventListener('click', (e) => {
  e.stopPropagation();
  langDropdown.classList.toggle('active');
  langBtn.setAttribute('aria-expanded', langDropdown.classList.contains('active'));
});

langDropdown.querySelectorAll('.lang-option').forEach(opt => {
  opt.addEventListener('click', (e) => {
    e.stopPropagation();
    const lang = opt.dataset.lang;
    currentLang = lang;
    langDropdown.querySelectorAll('.lang-option').forEach(o => o.classList.remove('active'));
    opt.classList.add('active');
    const label = opt.textContent;
    langBtn.innerHTML = `<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"/><path d="M2 12h20"/><path d="M12 2a15.3 15.3 0 014 10 15.3 15.3 0 01-4 10 15.3 15.3 0 01-4-10 15.3 15.3 0 014-10z"/></svg> ${label} <svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="6 9 12 15 18 9"/></svg>`;
    langDropdown.classList.remove('active');
  });
});

document.addEventListener('click', () => {
  langDropdown.classList.remove('active');
});

// ===== HERO CAROUSEL =====
let currentSlide = 0;
const totalSlides = 5;
let heroInterval;
const heroAutoDelay = 5000;

function showSlide(index) {
  const slides = document.querySelectorAll('.hero-slide');
  const dots = document.querySelectorAll('.hero-dot');
  slides.forEach(s => s.classList.remove('active'));
  dots.forEach(d => d.classList.remove('active'));
  slides[index].classList.add('active');
  dots[index].classList.add('active');
  currentSlide = index;
}

function nextSlide() { showSlide((currentSlide + 1) % totalSlides); }
function prevSlide() { showSlide((currentSlide - 1 + totalSlides) % totalSlides); }

function resetHeroAutoplay() {
  clearInterval(heroInterval);
  heroInterval = setInterval(nextSlide, heroAutoDelay);
}

