  dot.addEventListener('click', () => { showSlide(i); resetHeroAutoplay(); });
  heroDots.appendChild(dot);
}

document.getElementById('heroNext').addEventListener('click', () => { nextSlide(); resetHeroAutoplay(); });
document.getElementById('heroPrev').addEventListener('click', () => { prevSlide(); resetHeroAutoplay(); });

