      <div class="team-photo">${m.initials}</div>
      <div class="team-name">${m.name}</div>
      <div class="team-role">${m.title}</div>
      <div class="team-office">${m.office}</div>
      <p class="team-quote">"${m.quote}"</p>
      <a href="#" class="team-cta">Contact Leap Studio ${m.office} <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><line x1="5" y1="12" x2="19" y2="12"/><polyline points="12 5 19 12 12 19"/></svg></a>
    </div>
  `).join('');
}

teamTabs.querySelectorAll('.team-tab').forEach(tab => {
