    tab.classList.add('active');
    activeRegion = tab.dataset.region;
    renderTeam(activeRegion);
  });
});

renderTeam(activeRegion);

// ===== WORK SHOWCASE DRAG SCROLL =====
const workScroll = document.getElementById('workScroll');
let isDown = false, startX, scrollLeft;

workScroll.addEventListener('mousedown', (e) => {
  isDown = true;
  workScroll.classList.add('dragging');
  startX = e.pageX - workScroll.offsetLeft;
  scrollLeft = workScroll.scrollLeft;
});

workScroll.addEventListener('mouseleave', () => { isDown = false; workScroll.classList.remove('dragging'); });
workScroll.addEventListener('mouseup', () => { isDown = false; workScroll.classList.remove('dragging'); });

workScroll.addEventListener('mousemove', (e) => {
  if (!isDown) return;
  e.preventDefault();
  const x = e.pageX - workScroll.offsetLeft;
  const walk = (x - startX) * 2;
  workScroll.scrollLeft = scrollLeft - walk;
});

// ===== INSIGHTS GRID =====
const insightsGrid = document.getElementById('insightsGrid');
insightsGrid.innerHTML = insightsData.map(i => `
  <div class="insight-card">
