// ===== COOKIE CONSENT =====
const cookieBanner = document.getElementById('cookieBanner');
const cookieConsent = localStorage.getItem('leap-cookie-consent');

if (!cookieConsent) {
  setTimeout(() => { cookieBanner.style.display = 'flex'; }, 1500);
}

function hideCookieBanner() {
  cookieBanner.style.opacity = '0';
  cookieBanner.style.transform = 'translateX(-50%) translateY(20px)';
  cookieBanner.style.transition = 'opacity 0.3s, transform 0.3s';
  setTimeout(() => { cookieBanner.style.display = 'none'; }, 300);
}

document.getElementById('cookieAccept').addEventListener('click', () => {
  localStorage.setItem('leap-cookie-consent', 'accepted');
  hideCookieBanner();
});

document.getElementById('cookieDecline').addEventListener('click', () => {
  localStorage.setItem('leap-cookie-consent', 'declined');
  hideCookieBanner();
});

document.getElementById('cookieSettings').addEventListener('click', () => {
  localStorage.setItem('leap-cookie-consent', 'custom');
  hideCookieBanner();
});

document.getElementById('cookieSettingsLink').addEventListener('click', (e) => {
  e.preventDefault();
  localStorage.removeItem('leap-cookie-consent');
  cookieBanner.style.display = 'flex';
  cookieBanner.style.opacity = '1';
  cookieBanner.style.transform = 'translateX(-50%) translateY(0)';
});

// ===== SCROLL FADE-IN =====
const observer = new IntersectionObserver((entries) => {
  entries.forEach(entry => {
    if (entry.isIntersecting) {
      entry.target.classList.add('visible');
      observer.unobserve(entry.target);
    }
  });
}, { threshold: 0.15, rootMargin: '0px 0px -40px 0px' });

document.querySelectorAll('.fade-in').forEach(el => observer.observe(el));

// Init: show cookie banner check immediately in case setTimeout hasn't fired
if (!cookieConsent) {
  cookieBanner.style.display = 'flex';
}
</script>

